typedef unsigned long size_t;typedef unsigned __int128 U;extern void*calloc(size_t,size_t);extern void free(void*);extern int printf(const char*,...);extern int puts(const char*);
void pr(U x){if(x>=10)pr(x/10);printf("%d",(int)(x%10));}
int run(int N,int k){unsigned Z=1u<<N, nb[26]={0};for(int j=0;j<N;j++)for(int i=0;i<j;i++)if((j-i)%k==1){nb[j]|=1u<<i;nb[i]|=1u<<j;}unsigned char*E=calloc(Z,1);size_t*off=calloc(Z+1,sizeof(size_t));for(unsigned s=1;s<Z;s++){int j=__builtin_ctz(s);unsigned p=s^(1u<<j);E[s]=E[p]+__builtin_popcount(nb[j]&p);}for(unsigned s=0;s<Z;s++)off[s+1]=off[s]+E[s]/2+1;U*d=calloc(off[Z],sizeof(U));if(!d)return 2;d[0]=1;for(unsigned s=1;s<Z;s++){int degree=E[s];for(unsigned t=s;t;t&=t-1){int j=__builtin_ctz(t);unsigned p=s^(1u<<j);int shift=__builtin_popcount((nb[j]&((1u<<j)-1))&p),prevE=E[p];for(int e=shift;e<=degree/2&&e-shift<=prevE;e++){int a=e-shift;if(a>prevE-a)a=prevE-a;d[off[s]+e]+=d[off[p]+a];}}}int bad=0;U sum=0;printf("N %d k %d degree %d bytes %lu coefficients ",N,k,E[Z-1],(unsigned long)(off[Z]*sizeof(U)));for(int e=0;e<=E[Z-1];e++){int i=e;if(i>E[Z-1]-i)i=E[Z-1]-i;U a=d[off[Z-1]+i];sum+=a;pr(a);printf(",");if(e&&e<=E[Z-1]/2&&a<d[off[Z-1]+i-1])bad=1;}printf("\nunimodal %d sum ",!bad);pr(sum);puts("");free(d);free(E);free(off);return bad;}
